const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',book:'M4 4h6c2 0 2 1 2 2v15c0-2-2-3-4-3H4zM20 4h-6c-2 0-2 1-2 2v15c0-2 2-3 4-3h4z',file:'M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6',change:'M4 7h15l-4-4M20 17H5l4 4M19 7l-4 4M5 17l4-4',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',team:'M16 21v-2c0-3-2-4-6-4s-6 1-6 4v2M14 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M17 4a4 4 0 0 1 0 8M20 21v-2c0-2-1-3-3-4',question:'M9 9a3 3 0 1 1 5 2c-2 1-2 1-2 3M12 17h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',lock:'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5zM12 14v3',save:'M4 3h14l3 3v15H3V3zM7 3v6h10V3M7 21v-8h10v8',open:'M3 7h7l2 2h9l-3 11H3zM3 7V4h7l2 3',plus:'M12 5v14M5 12h14',chevron:'M9 5l7 7-7 7',check:'M5 12l4 4L19 6'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]??paths.file}"/></svg>`;
const badge=(label,type='')=>`<span class="badge ${type}">${esc(label)}</span>`;
const button=(label,action,extra='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const options=(items,selected='')=>items.map(([id,name])=>`<option value="${esc(id)}" ${id===selected?'selected':''}>${esc(name)}</option>`).join('');
